import sys

MOD = 998244353


def berlekamp_massey(sequence):
    c = [1]
    b_poly = [1]
    length = 0
    shift = 1
    last_discrepancy = 1

    for i in range(len(sequence)):
        discrepancy = sequence[i]
        for j in range(1, length + 1):
            discrepancy += c[j] * sequence[i - j]
        discrepancy %= MOD

        if discrepancy == 0:
            shift += 1
            continue

        old_c = c[:]
        coefficient = discrepancy * pow(last_discrepancy, MOD - 2, MOD) % MOD

        required = len(b_poly) + shift
        if len(c) < required:
            c.extend([0] * (required - len(c)))

        for j, value in enumerate(b_poly):
            c[j + shift] = (c[j + shift] - coefficient * value) % MOD

        if 2 * length <= i:
            length = i + 1 - length
            b_poly = old_c
            last_discrepancy = discrepancy
            shift = 1
        else:
            shift += 1

    return c[:length + 1]


def linear_recurrence_nth(initial, recurrence, index):
    order = len(recurrence)
    if index < len(initial):
        return initial[index]
    if order == 0:
        return 0

    def multiply(a, b):
        temp = [0] * (2 * order - 1)

        for i, x in enumerate(a):
            if x == 0:
                continue
            for j, y in enumerate(b):
                if y:
                    temp[i + j] += x * y

        for i in range(len(temp)):
            temp[i] %= MOD

        for degree in range(2 * order - 2, order - 1, -1):
            value = temp[degree]
            if value:
                for j in range(1, order + 1):
                    temp[degree - j] += value * recurrence[j - 1]

        return [x % MOD for x in temp[:order]]

    result = [0] * order
    result[0] = 1

    base = [0] * order
    if order == 1:
        base[0] = recurrence[0]
    else:
        base[1] = 1

    while index:
        if index & 1:
            result = multiply(result, base)
        base = multiply(base, base)
        index >>= 1

    return sum(result[i] * initial[i] for i in range(order)) % MOD


def solve():
    input_data = sys.stdin.buffer.read().split()
    n = int(input_data[0])
    target_length = int(input_data[1])
    words = [x.decode() for x in input_data[2:2 + n]]

    states = [None]
    state_id = {None: 0}
    transitions = []
    process_index = 0

    def get_state_id(state):
        if state not in state_id:
            state_id[state] = len(states)
            states.append(state)
        return state_id[state]

    def compare(a, b):
        if a == b:
            return None, len(a)
        if a.startswith(b):
            return (1, a[len(b):]), len(b)
        if b.startswith(a):
            return (2, b[len(a):]), len(a)
        return False, 0

