                    next_state, weight = compare(first, second)
                    if next_state is False:
                        continue
                    destination = get_state_id(next_state)
                    key = (destination, weight)
                    aggregated[key] = aggregated.get(key, 0) + 1
        else:
            side, residual = state
            for word in words:
                if side == 1:
