    for length in range(1, term_count):
        current = dp[length]
        for source, destination, weight, count in edges:
            if weight <= length:
                current[destination] += dp[length - weight][source] * count
        for i in range(state_count):
            current[i] %= MOD
        sequence.append(current[0])

    characteristic = berlekamp_massey(sequence)
    recurrence = [(-characteristic[i]) % MOD
                  for i in range(1, len(characteristic))]

    print(linear_recurrence_nth(sequence, recurrence, target_length))


