    dp = [[0] * state_count for _ in range(sequence_length)]
    dp[0][equal_state] = 1
    sequence = [0] * sequence_length

    for current_length in range(sequence_length):
        sequence[current_length] = dp[current_length][equal_state]
        row = dp[current_length]

        for source, value in enumerate(row):
            if value == 0:
                continue
            for destination, weight, count in edges[source]:
                next_length = current_length + weight
                if next_length < sequence_length:
                    dp[next_length][destination] = (
                        dp[next_length][destination] + value * count
                    ) % MOD

    recurrence = berlekamp_massey(sequence)
    answer = linear_recurrence_nth(
        sequence[:len(recurrence)],
        recurrence,
        target_length
    )
    print(answer)


